## C++ 代码
```cpp
#include <bits/stdc++.h>
using namespace std;

// 计算一个正整数 x 的数位和
int digitSum(long long x) {
    int sum = 0;
    while (x > 0) {
        sum += x % 10;
        x /= 10;
    }
    return sum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, k;
    cin >> n >> k;

    // 枚举的下界（不能小于 1）
    long long start = max(1LL, n - k);
    // 枚举的上界
    long long end = n + k;

    int ans = 0; // 记录数位和的最大值

    for (long long m = start; m <= end; m++) {
        int w_m = digitSum(m);
        if (w_m > ans) {
            ans = w_m;
        }
    }

    cout << ans << "\n";
    return 0;
}
```
