# 计算一个正整数 x 的数位和
def digit_sum(x):
    sum_digits = 0
    while x > 0:
        sum_digits += x % 10
        x //= 10
    return sum_digits

def main():
    n, k = map(int, input().split())

    # 枚举的下界（不能小于 1）
    start = max(1, n - k)
    # 枚举的上界
    end = n + k

    ans = 0  # 记录数位和的最大值

    for m in range(start, end + 1):
        w_m = digit_sum(m)
        if w_m > ans:
            ans = w_m

    print(ans)

if __name__ == "__main__":
    main()

```
